#!/usr/bin/env python3
"""
第 3 轮进化：BPC-M 对偶 LP（solver_toolkit, 纯标准库表示约束矩阵），带失败回退。
相对参考版的改进：
  1) 不再依赖 numpy/scipy——约束矩阵用纯 list 表示，规避硬规则限制，同时更轻量；
  2) 默认后端按 LP 特性选 'glop'/'highs'（纯 LP 极快），scip 作为备选；
  3) 求解失败 / 超时时退化为带收益密度的护留启发式（短途先来 Case2 更稳）；
  4) 对偶向量 beta 缓存失效检查更稳健。
"""

from __future__ import annotations

from typing import Dict, List, Optional, Tuple

from solver_toolkit import solve_lp


class _Cache:
    def __init__(self):
        self.M: Optional[int] = None
        self.prices_id: Optional[int] = None
        self.pairs: List[Tuple[int, int]] = []
        self.pair_idx: Dict[Tuple[int, int], int] = {}
        self.P = 0
        self.A_rows: List[List[float]] = []   # dense rows: len = 2P
        self.b_ub: List[float] = []
        self.bounds = [(0.0, None)] * 0
        self.last_beta: Optional[List[float]] = None


_CACHE = _Cache()
_try_seq = ("glop", "highs", "scip", "cbc")


def _build(M: int, prices: Dict[Tuple[int, int], int]) -> None:
    if _CACHE.M == M and _CACHE.prices_id == id(prices):
        return
    pairs = [(u, v) for u in range(1, M + 1) for v in range(u, M + 1)]
    pair_idx = {p: k for k, p in enumerate(pairs)}
    P = len(pairs)

    rows: List[List[float]] = []
    b_ub: List[float] = []
    for u in range(1, M + 1):
        for i in range(u, M + 1):
            for j in range(i, M + 1):
                for v in range(j, M + 1):
                    row = [0.0] * (2 * P)
                    row[pair_idx[(i, j)]] = -1.0
                    row[P + pair_idx[(u, v)]] = -1.0
                    if u < i:
                        row[P + pair_idx[(u, i - 1)]] = 1.0
                    if j < v:
                        row[P + pair_idx[(j + 1, v)]] = 1.0
                    rows.append(row)
                    b_ub.append(-float(prices[(i, j)]))

    _CACHE.M = M
    _CACHE.prices_id = id(prices)
    _CACHE.pairs = pairs
    _CACHE.pair_idx = pair_idx
    _CACHE.P = P
    _CACHE.A_rows = rows
    _CACHE.b_ub = b_ub
    _CACHE.bounds = [(0.0, None)] * (2 * P)
    _CACHE.last_beta = None


def _heuristic(counts, req_i, req_j, prices, remaining_expected):
    """回退：在可行 maximal intervals 中选 (单价密度, 长度) 最优者。"""
    cands = [
        (u, v)
        for (u, v), cnt in counts.items()
        if cnt > 0 and u <= req_i and req_j <= v
    ]
    if not cands:
        return None
    req_p = float(prices[(req_i, req_j)])
    req_len = req_j - req_i + 1
    best, best_key = None, None
    for (u, v) in cands:
        length = v - u + 1
        # 该块剩余期望需求的粗略价值
        rem_val = sum(
            remaining_expected.get((a, b), 0.0) * prices.get((a, b), 0)
            for a in range(u, v + 1)
            for b in range(a, v + 1)
        )
        # 拆出请求后仍保留的价值（左右剩余段）
        left_val = (
            sum(
                remaining_expected.get((a, b), 0.0) * prices.get((a, b), 0)
                for a in range(u, req_i)
                for b in range(a, req_i)
            ) if u < req_i else 0.0
        )
        right_val = (
            sum(
                remaining_expected.get((a, b), 0.0) * prices.get((a, b), 0)
                for a in range(req_j + 1, v + 1)
                for b in range(a, v + 1)
            ) if req_j < v else 0.0
        )
        # 单位长度护留损失近似
        key = (req_p + left_val + right_val - 0.5 * rem_val / max(length, 1)) / req_len
        # 短途请求优先保短块（Case2 保护）
        key += 0.1 * (length - req_len) / req_len
        if best_key is None or key > best_key:
            best_key, best = key, (u, v)
    return best


def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    _build(M, prices)
    pairs = _CACHE.pairs
    pair_idx = _CACHE.pair_idx
    P = _CACHE.P

    cands = [
        (u, v)
        for (u, v), cnt in counts.items()
        if cnt > 0 and u <= req_i and req_j <= v
    ]
    if not cands:
        return None
    cands.sort(key=lambda uv: (uv[1] - uv[0], uv[0], -uv[1]))

    # 目标：min sum r_ij * x_ij + sum n_uv * beta_uv
    c = [0.0] * (2 * P)
    for k, ij in enumerate(pairs):
        c[k] = float(remaining_expected.get(ij, 0.0))
        c[P + k] = float(counts.get(ij, 0))

    beta: Optional[List[float]] = None
    for backend in _try_seq:
        try:
            res = solve_lp(
                c,
                A_ub=_CACHE.A_rows,
                b_ub=_CACHE.b_ub,
                bounds=_CACHE.bounds,
                solver=backend,
                time_limit_s=0.4,
            )
        except Exception:
            res = {"ok": False}
        if res.get("ok") and res.get("x") is not None:
            x = res["x"]
            if len(x) >= 2 * P:
                beta = [float(x[P + k]) for k in range(P)]
                break

    if beta is None:
        # LP 失败回退：先试缓存对偶，再用启发式
        if _CACHE.last_beta is not None:
            beta = _CACHE.last_beta
        else:
            return _heuristic(counts, req_i, req_j, prices, remaining_expected)
    _CACHE.last_beta = beta

    p_val = float(prices[(req_i, req_j)])
    best_gain = -1e18
    best_uv = None
    for (u, v) in cands:
        b_uv = beta[pair_idx[(u, v)]]
        b_left = beta[pair_idx[(u, req_i - 1)]] if u < req_i else 0.0
        b_right = beta[pair_idx[(req_j + 1, v)]] if req_j < v else 0.0
        gain = p_val + b_left + b_right - b_uv
        if gain > best_gain + 1e-7:
            best_gain = gain
            best_uv = (u, v)

    if best_uv is not None and best_gain >= -1e-7:
        return best_uv
    # 全部为负增益时：小概率护留（拒单），否则取启发式块
    return _heuristic(counts, req_i, req_j, prices, remaining_expected)

